(function($){'use strict';window.ShahiLegalFlowSuite=window.ShahiLegalFlowSuite||{};ShahiLegalFlowSuite.init=function(){this.initAlerts();this.initTooltips();this.initConfirmDialogs();this.initFormValidation();this.initAjaxHandler();};ShahiLegalFlowSuite.initAlerts=function(){$(document).on('click','.shahi-alert .shahi-alert-close',function(e){e.preventDefault();$(this).closest('.shahi-alert').fadeOut(300,function(){$(this).remove();});});};ShahiLegalFlowSuite.initTooltips=function(){$('[data-shahi-tooltip]').each(function(){var $elem=$(this);var tooltipText=$elem.data('shahi-tooltip');$elem.hover(function(){var $tooltip=$('<div class="shahi-tooltip">'+tooltipText+'</div>');$('body').append($tooltip);var elemOffset=$elem.offset();var elemWidth=$elem.outerWidth();var tooltipWidth=$tooltip.outerWidth();$tooltip.css({top:elemOffset.top-$tooltip.outerHeight()-8,left:elemOffset.left+(elemWidth/2)-(tooltipWidth/2)});$tooltip.fadeIn(200);},function(){$('.shahi-tooltip').fadeOut(200,function(){$(this).remove();});});});};ShahiLegalFlowSuite.initConfirmDialogs=function(){$(document).on('click','[data-shahi-confirm]',function(e){var message=$(this).data('shahi-confirm')||shahiTemplate.i18n.confirm;if(!confirm(message)){e.preventDefault();return false;}});};ShahiLegalFlowSuite.initFormValidation=function(){$('.shahi-form-validate').on('submit',function(e){var $form=$(this);var isValid=true;$form.find('.shahi-error-message').remove();$form.find('.shahi-input-error').removeClass('shahi-input-error');$form.find('[required]').each(function(){var $field=$(this);var value=$field.val().trim();if(!value){isValid=false;$field.addClass('shahi-input-error');$field.after('<span class="shahi-error-message">'+shahiTemplate.i18n.required+'</span>');}});$form.find('[type="email"]').each(function(){var $field=$(this);var value=$field.val().trim();if(value&&!ShahiLegalFlowSuite.isValidEmail(value)){isValid=false;$field.addClass('shahi-input-error');$field.after('<span class="shahi-error-message">Invalid email address</span>');}});if(!isValid){e.preventDefault();var $firstError=$form.find('.shahi-input-error').first();if($firstError.length){$('html,body').animate({scrollTop:$firstError.offset().top-100},300);}}return isValid;});};ShahiLegalFlowSuite.initAjaxHandler=function(){$(document).ajaxError(function(event,jqxhr,settings,thrownError){if(jqxhr.status===403){ShahiLegalFlowSuite.showNotice('Permission denied. Please refresh the page.','error');}else if(jqxhr.status===500){ShahiLegalFlowSuite.showNotice(shahiTemplate.i18n.error,'error');}});};ShahiLegalFlowSuite.ajax=function(action,data,successCallback,errorCallback){data=data||{};data.action=action;data.nonce=shahiTemplate.nonce;$.ajax({url:shahiTemplate.ajaxurl,type:'POST',data:data,success:function(response){if(response.success){if(typeof successCallback==='function'){successCallback(response.data);}}else{if(typeof errorCallback==='function'){errorCallback(response.data);}else{ShahiLegalFlowSuite.showNotice(response.data.message||shahiTemplate.i18n.error,'error');}}},error:function(jqxhr,textStatus,error){if(typeof errorCallback==='function'){errorCallback({message:error});}else{ShahiLegalFlowSuite.showNotice(shahiTemplate.i18n.error,'error');}}});};ShahiLegalFlowSuite.showNotice=function(message,type,duration){type=type||'info';duration=duration||5000;var $notice=$('<div class="shahi-alert shahi-alert-'+type+'">'+'<span>'+message+'</span>'+'<button class="shahi-alert-close">&times;</button>'+'</div>');$('.shahi-legalflowsuite-admin').prepend($notice);$notice.fadeIn(300);if(duration>0){setTimeout(function(){$notice.fadeOut(300,function(){$(this).remove();});},duration);}};ShahiLegalFlowSuite.showLoading=function(){if($('.shahi-loading-overlay').length===0){var $overlay=$('<div class="shahi-loading-overlay">'+'<div class="shahi-spinner"></div>'+'</div>');$('body').append($overlay);$overlay.fadeIn(200);}};ShahiLegalFlowSuite.hideLoading=function(){$('.shahi-loading-overlay').fadeOut(200,function(){$(this).remove();});};ShahiLegalFlowSuite.isValidEmail=function(email){var re=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;return re.test(email);};ShahiLegalFlowSuite.isValidUrl=function(url){try{new URL(url);return true;}catch(e){return false;}};ShahiLegalFlowSuite.debounce=function(func,wait){var timeout;return function(){var context=this;var args=arguments;clearTimeout(timeout);timeout=setTimeout(function(){func.apply(context,args);},wait);};};ShahiLegalFlowSuite.formatNumber=function(num){return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g,',');};ShahiLegalFlowSuite.getUrlParam=function(name){var url=new URL(window.location.href);return url.searchParams.get(name);};ShahiLegalFlowSuite.copyToClipboard=function(text){var $temp=$('<textarea>');$('body').append($temp);$temp.val(text).select();var success=document.execCommand('copy');$temp.remove();if(success){ShahiLegalFlowSuite.showNotice('Copied to clipboard!','success',2000);}return success;};ShahiLegalFlowSuite.escapeHtml=function(html){var div=document.createElement('div');div.textContent=html;return div.innerHTML;};$(document).ready(function(){ShahiLegalFlowSuite.init();});})(jQuery);